import os
import sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__))); import bits
out = []
w = out.append
w('''# Bytes' tail-recursive loops equal their direct recursive specs (BND-84).
# Generated by a bit-trie case splitter for the literal patterns; this module
# deliberately does not import LAWS.
import Base
import ../src/http/bytes.bend as B
import ./text.bend as TP

def and_assoc(a: Bool, +b: Bool, +c: Bool) -> {(a && b) && c == a && (b && c) : Bool}:
  match a:
    case True{}:
      {==}
    case False{}:
      {==}

def and_true_right(a: Bool) -> {a && True{} == a : Bool}:
  match a:
    case True{}:
      {==}
    case False{}:
      {==}

# Moves one verdict from the accumulator into the conjunction.
def shift(+acc: Bool, +x: Bool, +rest: Bool, -l: Bool, ih: {l == (acc && x) && rest : Bool}) -> {l == acc && (x && rest) : Bool}:
  Equal.trans(Bool, l, (acc && x) && rest, acc && (x && rest), ih, and_assoc(acc, x, rest))

# ---- encode / ascii ----

def encode_reverse(+s: String, +r: String, +acc: List<&2, U32>) -> {B.encode_go(String.reverse.go(s, r), acc) == B.encode_go(r, List.append(&2, U32, B.encode_spec(s), acc)) : List<&2, U32>}:
  match s:
    case SNil{}:
      {==}
    case SCon{Chr{c}, t}:
      encode_reverse(t, SCon{Chr{c}, r}, acc)

def encode_equiv(+s: String) -> {B.encode(s) == B.encode_spec(s) : List<&2, U32>}:
  Equal.trans(List<&2, U32>, B.encode(s), List.append(&2, U32, B.encode_spec(s), []), B.encode_spec(s), encode_reverse(s, "", []), TP.list_append_nil(U32, B.encode_spec(s)))

def encode_go_equiv(+s: String, +acc: List<&2, U32>) -> {B.encode_go(String.reverse(s), acc) == List.append(&2, U32, B.encode_spec(s), acc) : List<&2, U32>}:
  encode_reverse(s, "", acc)

def ascii_reverse(+xs: List<&2, U32>, +r: List<&2, U32>, +acc: String) -> {B.ascii_go(List.reverse.go(&2, U32, xs, r), acc) == B.ascii_go(r, String.append(B.ascii_spec(xs), acc)) : String}:
  match xs:
    case Nil{}:
      {==}
    case h <> t:
      ascii_reverse(t, h <> r, acc)

def ascii_equiv(+xs: List<&2, U32>) -> {B.ascii(xs) == B.ascii_spec(xs) : String}:
  Equal.trans(String, B.ascii(xs), String.append(B.ascii_spec(xs), ""), B.ascii_spec(xs), ascii_reverse(xs, [], ""), TP.string_append_nil(B.ascii_spec(xs)))

def ascii_go_equiv(+xs: List<&2, U32>, +acc: String) -> {B.ascii_go(List.reverse(&2, U32, xs), acc) == String.append(B.ascii_spec(xs), acc) : String}:
  ascii_reverse(xs, [], acc)

# ---- token / value ----

def token_go_equiv(+s: String, +acc: Bool) -> {B.token_go(s, acc) == acc && B.token_tail_spec(s) : Bool}:
  match s:
    case SNil{}:
      Equal.sym(Bool, acc && True{}, acc, and_true_right(acc))
    case SCon{Chr{c}, t}:
      shift(acc, B.tchar(c), B.token_tail_spec(t), B.token_go(t, acc && B.tchar(c)), token_go_equiv(t, acc && B.tchar(c)))

def token_tail_equiv(+s: String) -> {B.token_tail(s) == B.token_tail_spec(s) : Bool}:
  token_go_equiv(s, True{})

def value_go_equiv(+xs: List<&2, U32>, +acc: Bool) -> {B.value_go(xs, acc) == acc && B.value_spec(xs) : Bool}:
  match xs:
    case Nil{}:
      Equal.sym(Bool, acc && True{}, acc, and_true_right(acc))
    case h <> t:
      shift(acc, B.value_octet(h), B.value_spec(t), B.value_go(t, acc && B.value_octet(h)), value_go_equiv(t, acc && B.value_octet(h)))

def value_equiv(+xs: List<&2, U32>) -> {B.value(xs) == B.value_spec(xs) : Bool}:
  value_go_equiv(xs, True{})

def fold_equiv(+s: String) -> {B.fold(s) == String.to_lower(s) : String}:
  TP.lower_equiv(s)

def append_equiv(+xs: List<&2, U32>, +ys: List<&2, U32>) -> {B.append(xs, ys) == List.append(&2, U32, xs, ys) : List<&2, U32>}:
  TP.bytes_append_equiv(xs, ys)

# ---- one step of each loop, for proofs that unfold the earlier recursion ----

def token_tail_cons(+c: U32, +t: String) -> {B.token_tail(SCon{Chr{c}, t}) == B.tchar(c) && B.token_tail(t) : Bool}:
  Equal.trans(Bool, B.token_go(t, B.tchar(c)), B.tchar(c) && B.token_tail_spec(t), B.tchar(c) && B.token_tail(t), token_go_equiv(t, B.tchar(c)), Equal.cong(Bool, Bool, x => B.tchar(c) && x, B.token_tail_spec(t), B.token_tail(t), Equal.sym(Bool, B.token_tail(t), B.token_tail_spec(t), token_tail_equiv(t))))

def value_cons(+h: U32, +t: List<&2, U32>) -> {B.value(h <> t) == B.value_octet(h) && B.value(t) : Bool}:
  Equal.trans(Bool, B.value_go(t, B.value_octet(h)), B.value_octet(h) && B.value_spec(t), B.value_octet(h) && B.value(t), value_go_equiv(t, B.value_octet(h)), Equal.cong(Bool, Bool, x => B.value_octet(h) && x, B.value_spec(t), B.value(t), Equal.sym(Bool, B.value(t), B.value_spec(t), value_equiv(t))))

def encode_cons(+c: U32, +t: String) -> {B.encode(SCon{Chr{c}, t}) == c <> B.encode(t) : List<&2, U32>}:
  Equal.trans(List<&2, U32>, B.encode(SCon{Chr{c}, t}), c <> B.encode_spec(t), c <> B.encode(t), encode_equiv(SCon{Chr{c}, t}), Equal.cong(List<&2, U32>, List<&2, U32>, x => c <> x, B.encode_spec(t), B.encode(t), Equal.sym(List<&2, U32>, B.encode(t), B.encode_spec(t), encode_equiv(t))))

def append_cons(+h: U32, +t: List<&2, U32>, +ys: List<&2, U32>) -> {B.append(h <> t, ys) == h <> B.append(t, ys) : List<&2, U32>}:
  Equal.trans(List<&2, U32>, B.append(h <> t, ys), h <> List.append(&2, U32, t, ys), h <> B.append(t, ys), append_equiv(h <> t, ys), Equal.cong(List<&2, U32>, List<&2, U32>, x => h <> x, List.append(&2, U32, t, ys), B.append(t, ys), Equal.sym(List<&2, U32>, B.append(t, ys), List.append(&2, U32, t, ys), append_equiv(t, ys))))

# ---- uri ----

def uri_plain(+c: U32, +t: String, +q: Bool, +acc: Bool, ih: {B.uri_go(t, q, acc && B.uri_char(c, q)) == (acc && B.uri_char(c, q)) && B.uri_spec(t, q) : Bool}) -> {B.uri_go(t, q, acc && B.uri_char(c, q)) == acc && (B.uri_char(c, q) && B.uri_spec(t, q)) : Bool}:
  shift(acc, B.uri_char(c, q), B.uri_spec(t, q), B.uri_go(t, q, acc && B.uri_char(c, q)), ih)

def uri_go_equiv(+s: String, +q: Bool, +acc: Bool) -> {B.uri_go(s, q, acc) == acc && B.uri_spec(s, q) : Bool}:
  match s:
    case SNil{}:
      Equal.sym(Bool, acc && True{}, acc, and_true_right(acc))
    case SCon{Chr{37}, SCon{Chr{a}, SCon{Chr{b}, t}}}:
      shift(acc, B.hex(a) && B.hex(b), B.uri_spec(t, q), B.uri_go(t, q, acc && (B.hex(a) && B.hex(b))), uri_go_equiv(t, q, acc && (B.hex(a) && B.hex(b))))
    case SCon{Chr{37}, SNil{}}:
      uri_plain(37, SNil{}, q, acc, uri_go_equiv(SNil{}, q, acc && B.uri_char(37, q)))
    case SCon{Chr{37}, SCon{h, SNil{}}}:
      uri_plain(37, SCon{h, SNil{}}, q, acc, uri_go_equiv(SCon{h, SNil{}}, q, acc && B.uri_char(37, q)))''')
for p in bits.others([37]):
    w('''    case SCon{Chr{%s}, t}:
      uri_plain(%s, t, q, acc, uri_go_equiv(t, q, acc && B.uri_char(%s, q)))''' % (p, p, p))
w('''
def uri_equiv(+s: String, +q: Bool) -> {B.uri(s, q) == B.uri_spec(s, q) : Bool}:
  uri_go_equiv(s, q, True{})

# ---- split_target ----

def onto(rev: String, parts: String & Maybe<&2, String>) -> String & Maybe<&2, String>:
  (p, q) = parts
  (String.reverse.go(rev, p), q)

def onto_push(+rev: String, c: Char, parts: String & Maybe<&2, String>) -> {onto(SCon{c, rev}, parts) == onto(rev, B.split_push(c, parts)) : String & Maybe<&2, String>}:
  match parts:
    case (p, q):
      {==}

def target_plain(+c: Char, +t: String, +rev: String, ih: {B.split_target_go(t, SCon{c, rev}) == onto(SCon{c, rev}, B.split_target_spec(t)) : String & Maybe<&2, String>}) -> {B.split_target_go(t, SCon{c, rev}) == onto(rev, B.split_push(c, B.split_target_spec(t))) : String & Maybe<&2, String>}:
  Equal.trans(String & Maybe<&2, String>, B.split_target_go(t, SCon{c, rev}), onto(SCon{c, rev}, B.split_target_spec(t)), onto(rev, B.split_push(c, B.split_target_spec(t))), ih, onto_push(rev, c, B.split_target_spec(t)))

def split_target_go_equiv(+s: String, +rev: String) -> {B.split_target_go(s, rev) == onto(rev, B.split_target_spec(s)) : String & Maybe<&2, String>}:
  match s:
    case SNil{}:
      {==}
    case SCon{Chr{63}, t}:
      {==}''')
for p in bits.others([63]):
    w('''    case SCon{Chr{%s}, t}:
      target_plain(Chr{%s}, t, rev, split_target_go_equiv(t, SCon{Chr{%s}, rev}))''' % (p, p, p))
w('''
def onto_empty(parts: String & Maybe<&2, String>) -> {onto("", parts) == parts : String & Maybe<&2, String>}:
  match parts:
    case (p, q):
      {==}

def split_target_equiv(+s: String) -> {B.split_target(s) == B.split_target_spec(s) : String & Maybe<&2, String>}:
  Equal.trans(String & Maybe<&2, String>, B.split_target(s), onto("", B.split_target_spec(s)), B.split_target_spec(s), split_target_go_equiv(s, ""), onto_empty(B.split_target_spec(s)))
''')
print("\n".join(out))
